base = list(csv.DictReader((root/'data/words.tsv').open(encoding='utf-8'), delimiter='\t'))
used = {w['word'].lower() for w in base}
dictionary = {}
with open(sys.argv[1], encoding='utf-8') as f:
    for row in csv.DictReader(f):
        if row['word'].islower() and row['translation']:
            dictionary[row['word']] = row
extra = []
for topic, candidates in groups.items():
    added = 0
    for word in candidates.lower().split():
        if word in used or word not in dictionary: continue
        row = dictionary[word]
        extra.append(dict(word=word, topic=topic, phonetic=row['phonetic'], pos=row['pos'], meaning=row['translation'].replace('\\n', '\n'), example='', translation='', source='ECDICT · MIT · https://github.com/skywind3000/ECDICT'))
        used.add(word); added += 1
        if added == 170: break
    if added != 170: raise ValueError(f'{topic}: only {added}/170 candidates')
(root/'data/extended-words.json').write_text(json.dumps(extra, ensure_ascii=False, indent=2)+'\n', encoding='utf-8')
print(f'Prepared {len(base)+len(extra)} unique words, 200 per domain.')
